type ZipMenuManifestItem = { category: string; name: string; file: string };
async function extractZipImages(file: File): Promise<{ images: File[]; manifest: ZipMenuManifestItem[] | null }> {
  if (file.size > 150 * 1024 * 1024) throw new Error("حجم ملف ZIP أكبر من 150 ميجابايت.");
  const buffer = await file.arrayBuffer(); const view = new DataView(buffer); const decoder = new TextDecoder();
  let eocd = -1;
  for (let i = Math.max(0, view.byteLength - 22 - 65535); i <= view.byteLength - 22; i++) if (view.getUint32(i, true) === 0x06054b50) eocd = i;
  if (eocd < 0) throw new Error("ملف ZIP غير صالح أو غير مكتمل.");
  const count = view.getUint16(eocd + 10, true); let offset = view.getUint32(eocd + 16, true);
  if (count > 5000) throw new Error("ملف ZIP يحتوي على عدد ملفات أكبر من المسموح (5000).");
  const images: File[] = []; let manifest: ZipMenuManifestItem[] | null = null;
  for (let i = 0; i < count; i++) {
    if (view.getUint32(offset, true) !== 0x02014b50) throw new Error("تعذر قراءة محتويات ملف ZIP.");
    const method = view.getUint16(offset + 10, true); const compressedSize = view.getUint32(offset + 20, true);
    const nameLength = view.getUint16(offset + 28, true); const extraLength = view.getUint16(offset + 30, true); const commentLength = view.getUint16(offset + 32, true);
    const localOffset = view.getUint32(offset + 42, true); const name = decoder.decode(new Uint8Array(buffer, offset + 46, nameLength)).replace(/\\/g, "/");
    offset += 46 + nameLength + extraLength + commentLength;
    const isManifest = name.toLowerCase() === "manifest.json"; const isImage = /\.(jpe?g|png|webp)$/i.test(name) && !name.endsWith("/");
    if (!isManifest && !isImage) continue;
    if (view.getUint32(localOffset, true) !== 0x04034b50) continue;
    const localNameLength = view.getUint16(localOffset + 26, true); const localExtraLength = view.getUint16(localOffset + 28, true);
    const dataStart = localOffset + 30 + localNameLength + localExtraLength; const compressed = buffer.slice(dataStart, dataStart + compressedSize);
    let data: ArrayBuffer;
    if (method === 0) data = compressed;
    else if (method === 8) {
      if (typeof DecompressionStream === "undefined") throw new Error("المتصفح لا يدعم فك ضغط ZIP. حدّث Safari أو استخدم جهاز كمبيوتر.");
      data = await new Response(new Blob([compressed]).stream().pipeThrough(new DecompressionStream("deflate-raw" as CompressionFormat))).arrayBuffer();
    } else continue;
    if (isManifest) {
      try { const parsed = JSON.parse(decoder.decode(new Uint8Array(data))); if (Array.isArray(parsed) && parsed.every((x:any)=>x && typeof x.category==="string" && typeof x.name==="string" && typeof x.file==="string")) manifest = parsed; }
      catch { throw new Error("ملف manifest.json داخل ZIP غير صالح."); }
      continue;
    }
    const lower=name.toLowerCase(); const type=lower.endsWith(".png")?"image/png":lower.endsWith(".webp")?"image/webp":"image/jpeg";
    const image=new File([data],name.split("/").pop()||"image",{type}); Object.defineProperty(image,"webkitRelativePath",{value:name}); images.push(image);
  }
  if (!images.length) throw new Error("لم نعثر على صور JPG أو PNG أو WEBP داخل ملف ZIP.");
  return {images,manifest};
}
